38	export async function generate(input: {
39	  occasion: UiOccasion;
40	  formality: number | null;
41	  /** Refine "Lean into" colour families (`COLOR_FAMILIES` keys). A preference, not a filter. */
42	  lean: string[];
43	  /** Explicit user action only — the one way to spend an AI call on a day already answered. */
44	  regenerate?: boolean;
45	  city?: { lat: number; lon: number; label: string; source: LocationSource };
46	}): Promise<GenerateResult> {
47	  try {
48	    const supabase = await createClient();
49	    const {
50	      data: { user },
51	    } = await supabase.auth.getUser();
52	    if (!user) return { status: "error", message: "Not signed in" };
53	
54	    const { data: profile } = await supabase
55	      .from("profiles")
56	      .select(
57	        "archetype, formality_min, formality_max, location_lat, location_lon, location_label, location_source",
58	      )
59	      .eq("id", user.id)
60	      .single();
61	    const { data: itemsRaw } = await supabase
62	      .from("items")
63	      .select("*")
64	      .eq("user_id", user.id)
65	      .eq("archived", false);
66	    const items = itemsRaw ?? [];
67	    const byId = new Map(items.map((i) => [i.id, i]));
68	
69	    const loc = resolveLocation({ input: input.city, profile });
70	
71	    const now = new Date();
72	    const f = await fetchForecast(loc.lat, loc.lon);
73	    const advice = laterAdvice(f.hourly);
74	    const weather: WeatherPayload = {
75	      tempC: f.tempC,
76	      feelsLikeC: f.feelsLikeC,
77	      condition: f.condition,
78	      cityLabel: loc.label,
79	      timezone: f.timezone,
80	      locationOrigin: loc.origin,
81	      laterSentence: advice.sentence,
82	      adviceClause: advice.adviceClause,
83	      laterLabel: "Later",
84	      hourly: f.hourly,
85	    };
86	
87	    const today = localDateFor(now, f.timezone);
88	
89	    // The daily drop (Decision 5): today's looks are generated once and then
90	    // read back. Only an explicit regenerate spends an AI call on a day the
91	    // stylist has already answered.
92	    if (!input.regenerate) {
93	      const stored = await loadDailyLooks(user.id, input.occasion, today);
94	      if (stored?.length) {
95	        const paths = Array.from(
96	          new Set(
97	            stored
98	              .flatMap((s) => s.pieces.map((p) => byId.get(p.itemId)))
99	              .filter((it): it is NonNullable<typeof it> => Boolean(it))
100	              .map((it) => displayPath(it)),
101	          ),
102	        );
103	        const signed = await signItemImages(paths);
104	        const looks = reassembleLooks(stored, byId, signed, (id) => {
105	          const it = byId.get(id);
106	          return it ? displayPath(it) : undefined;
107	        });
108	        // null = the closet changed under the stored set; fall through and
109	        // regenerate rather than showing an outfit with a hole in it.
110	        if (looks) return { status: "ok", weather, looks };
111	      }
112	    }
113	
114	    await assertCanGenerate(user.id);
115	
116	    const candItems: CandidateItem[] = items.map((i) => ({
117	      id: i.id,
118	      category: i.category,
119	      colors: i.colors ?? [],
120	      formality: i.formality,
121	      seasons: i.seasons ?? [],
122	      material: i.material,
123	    }));
124	    // Occasion gives the context; the user's onboarding dress codes narrow it;
125	    // an explicit Refine formality overrides both.
126	    const band = applyFormalityOverride(
127	      personalBand(input.occasion, profile),
128	      input.formality,
129	    );
130	    const candidateArgs = {
131	      band,
132	      weather: { tempC: f.tempC, rain: f.hourly.some((h) => h.isNow && h.rain) },
133	      season: currentSeason(now),
134	      excludeItemIds: [],
135	      maxAccessories: 1,
136	    };
137	    const combos = buildCandidates(candItems, candidateArgs);
138	    if (combos.length === 0) {
139	      return { status: "empty", weather, missing: missingCategory(candItems, candidateArgs) };
140	    }
141	
142	    const aesthetic = profile?.archetype ? [profile.archetype] : [];
143	    // The Refine colour pick lands here, in ranking — not in candidate building.
144	    // It reorders the shortlist toward the requested families and is dropped
145	    // silently when the closet cannot honour it.
146	    //
147	    // Rank everything, then spread the shortlist across the wardrobe before the
148	    // re-ranker sees it. Taking the top 20 by score alone clusters — a neutral
149	    // top harmonises with everything, so it occupies most of the list, and "the
150	    // best 3" of a clustered list is three versions of one outfit. Diversifying
151	    // the INPUT makes the model's three distinct by construction.
152	    const ranked = rankTopN(combos, { aesthetic, band, lean: input.lean }, combos.length);
153	    const top = diversify(ranked, 20);
154	
155	    const { picks } = await rerank({
156	      combos: top.map((t) =>
157	        t.items.map((ci) => {
158	          const it = byId.get(ci.id)!;
159	          return { category: it.category, subcategory: it.subcategory, colors: it.colors ?? [] };
160	        }),
161	      ),
162	      aesthetic,
163	      occasion: input.occasion,
164	      weatherLabel: f.condition,
165	      tempC: f.tempC,
166	    });
167	
168	    const paths = Array.from(
169	      new Set(top.flatMap((t) => t.items.map((ci) => displayPath(byId.get(ci.id)!)))),
170	    );
171	    const signed = await signItemImages(paths);
172	
173	    // `rerank` already dropped picks that repeat a combo or point outside the
174	    // shortlist, so every index here resolves. It previously fell back to
175	    // `top[0]` for an unknown index, which turned a bad index into a duplicate
176	    // of the first look rather than into one fewer look.
177	    const looks: Look[] = picks.map((p) => {
178	      const combo = top[p.combo_index].items;
179	      const dbItems = combo.map((ci) => byId.get(ci.id)!);
180	      const slots = layoutForLook(dbItems.map((d) => ({ category: d.category })));
181	      const pieces: LookPiece[] = dbItems.map((d, idx) => ({
182	        itemId: d.id,
183	        category: d.category,
184	        subcategory: d.subcategory ?? null,
185	        brand: d.brand ?? null,
186	        name: d.name ?? null,
187	        colors: d.colors ?? [],
188	        cutoutUrl: signed.get(displayPath(d)) ?? "",
189	        slot: slots[idx],
190	      }));
191	      return { name: p.name, why: p.why, pieces, anchorIndex: staggerOrder(slots)[0] };
192	    });
193	
194	    // Fire-and-forget would be simpler, but a failed write means the user pays
195	    // for another AI call on their next tap — worth awaiting.
196	    await saveDailyLooks(user.id, input.occasion, today, weather, looks);
197	
198	    return { status: "ok", weather, looks };
199	  } catch (e) {
200	    console.error("[generate] failed:", e);
201	    return { status: "error", message: e instanceof Error ? e.message : "Generation failed" };
202	  }
203	}
