238	export async function predictDefaultOccasion(): Promise<{ occasion: UiOccasion; reason: string }> {
239	  const supabase = await createClient();
240	  const {
241	    data: { user },
242	  } = await supabase.auth.getUser();
243	  if (!user) return { occasion: "everyday", reason: defaultReason("everyday") };
244	
245	  const { data: profile } = await supabase
246	    .from("profiles")
247	    .select("occasions, location_timezone")
248	    .eq("id", user.id)
249	    .single();
250	
251	  const tz = profile?.location_timezone ?? "UTC";
252	  const occasion = predictOccasion(new Date(), tz, profile?.occasions ?? []);
253	  return { occasion, reason: defaultReason(occasion) };
254	}
