256	/**
257	 * Record that the user chose an occasion other than the predicted default.
258	 * Fire-and-forget: the caller does not await the outcome, and a failure here
259	 * must never affect the looks. Guards `chosen === predicted` so a no-op tap is
260	 * not logged as an override.
261	 */
262	export async function logOccasionOverride(input: {
263	  predicted: UiOccasion;
264	  chosen: UiOccasion;
265	}): Promise<void> {
266	  if (input.chosen === input.predicted) return;
267	
268	  const supabase = await createClient();
269	  const {
270	    data: { user },
271	  } = await supabase.auth.getUser();
272	  if (!user) return;
273	
274	  const { data: profile } = await supabase
275	    .from("profiles")
276	    .select("location_timezone")
277	    .eq("id", user.id)
278	    .single();
279	
280	  const today = localDateFor(new Date(), profile?.location_timezone ?? "UTC");
281	  await recordOverride(user.id, today, input.predicted, input.chosen);
282	}
