1	import Anthropic from "@anthropic-ai/sdk";
2	import { z } from "zod";
3	import { forStructuredOutput } from "@/lib/ai/tagging-schema";
4	
5	// Text-only re-rank (CLAUDE.md Decision 3, mode 2): the model sees tag DESCRIPTIONS,
6	// never images. It returns the best 3 with a look name + one-sentence "why".
7	
8	export type DescItem = { category: string; subcategory?: string | null; colors: string[] };
9	
10	export function describeCombos(combos: DescItem[][]): string {
11	  return combos
12	    .map(
13	      (c, i) =>
14	        `${i}. ` +
15	        c.map((it) => `${it.subcategory ?? it.category} (${it.colors.join("/")})`).join(" + "),
16	    )
17	    .join("\n");
18	}
19	
20	/**
21	 * Display budget for a look name — comfortably fits the "≤4 words" the prompt
22	 * asks for ("The Impeccable Charcoal Layer" = 29) with room to spare.
23	 */
24	export const NAME_MAX = 40;
25	
26	/**
27	 * Clamp a name to NAME_MAX on a word boundary.
28	 *
29	 * A name is decoration; the "why" is the product. This is a `transform`, not a
30	 * `.max()`, on purpose: the cap is never enforced on the model — CLAUDE.md's
31	 * `forStructuredOutput` strips `maxLength` because the API 400s on it — so a
32	 * hard bound here existed only as a post-hoc throw that failed the ENTIRE
33	 * generation and surfaced as "Couldn't reach the stylist". Repair, don't reject.
34	 */
35	export function clampName(raw: string): string {
36	  const s = raw.trim();
37	  if (s.length <= NAME_MAX) return s;
38	  const cut = s.slice(0, NAME_MAX);
39	  const lastSpace = cut.lastIndexOf(" ");
40	  return (lastSpace > 0 ? cut.slice(0, lastSpace) : cut).trimEnd();
41	}
42	
43	// The WIRE shape — what we ask the model for. Kept transform-free because
44	// `z.toJSONSchema` cannot represent a transform ("Transforms cannot be
45	// represented in JSON Schema"); the repair belongs on the way in, not the way out.
46	const PickShape = z.object({
47	  combo_index: z.number().int(),
48	  name: z.string().min(1),
49	  why: z.string().min(1),
50	});
51	
52	// Sanitised JSON Schema for Anthropic's output_config.format (strips min/max keywords
53	// that would 400 — real bounds re-enforced by RerankSchema.parse after the call).
54	export const rerankJsonSchema = forStructuredOutput(
55	  z.toJSONSchema(z.object({ picks: z.array(PickShape).length(3) })),
56	) as Record<string, unknown>;
57	
58	// The PARSE shape — same fields, plus the name repair.
59	export const RerankSchema = z.object({
60	  picks: z.array(PickShape.extend({ name: z.string().min(1).transform(clampName) })).length(3),
61	});
62	export type RerankResult = z.infer<typeof RerankSchema>;
63	
64	/**
65	 * The variety instruction.
66	 *
67	 * "Pick the best 3" alone produces three versions of one outfit: the model is
68	 * optimising a single notion of "best", and the candidates handed to it are
69	 * ranked, so the top of the list is naturally near-identical. Asking for the
70	 * best 3 without asking for three DIFFERENT ones gets exactly what it asks for.
71	 */
72	export const RERANK_VARIETY_RULE =
73	  "The three must be genuinely different outfits, not variations of one: no two may share the same top, and no two may share the same bottom. If the candidates cannot give you three that differ, prefer variety over a marginally higher-scoring repeat.";
74	
75	type Pick = { combo_index: number; name: string; why: string };
76	
77	/**
78	 * Drop picks that reuse a combo the model already chose.
79	 *
80	 * The schema checks the array LENGTH, never that the indices differ, so a model
81	 * returning [4, 4, 7] rendered the same outfit twice. Repair rather than reject
82	 * — the same stance as `clampName` above: a duplicated index should cost the
83	 * user one look, not the whole generation.
84	 *
85	 * Returning fewer than three is fine and deliberate: the daily drop already
86	 * tolerates a variable count (`saveDailyLooks` is delete-then-insert for exactly
87	 * this reason), and two real looks beat three where two are the same.
88	 */
89	export function dedupePicks(picks: Pick[], comboCount?: number): Pick[] {
90	  const seen = new Set<number>();
91	  return picks.filter((p) => {
92	    // An index outside the shortlist used to fall back to the FIRST combo, so
93	    // two bad indices rendered the same outfit twice — duplicates that survive
94	    // de-duplication because the indices themselves differ. Drop them instead.
95	    if (comboCount != null && (p.combo_index < 0 || p.combo_index >= comboCount)) return false;
96	    if (seen.has(p.combo_index)) return false;
97	    seen.add(p.combo_index);
98	    return true;
99	  });
100	}
101	
102	export async function rerank(args: {
103	  combos: DescItem[][];
104	  aesthetic: string[];
105	  occasion: string;
106	  weatherLabel: string;
107	  tempC: number;
108	}): Promise<RerankResult> {
109	  const prompt = `You are a personal stylist. The user's aesthetic is ${
110	    args.aesthetic.join(", ") || "understated, modern menswear"
111	  }. Occasion: ${args.occasion}. Weather: ${args.weatherLabel}, ${args.tempC}°C.
112	Here are candidate outfits (already filtered and scored), one per line:
113	${describeCombos(args.combos)}
114	
115	Pick the best 3. ${RERANK_VARIETY_RULE}
116	
117	For each return: its combo_index; a short evocative NAME (≤4 words and at most ${NAME_MAX} characters, e.g. "The Off-Duty Camel"); and ONE warm, specific sentence ("why") that references the colours/pieces (e.g. "the camel knit warms the grey trousers and picks up the loafers"). Return exactly 3 picks, each with a DIFFERENT combo_index.`;
118	
