import { describe, it, expect } from "vitest";
import { buildCandidates, type CandidateItem } from "@/lib/generator/candidates";
import { rankTopN } from "@/lib/generator/rank";
import { diversify } from "@/lib/generator/diversity";

/** A realistic 20-item closet, all mutually compatible. */
function closet(): CandidateItem[] {
  const cats = ["Tops", "Bottoms", "Shoes", "Outerwear", "Accessories"];
  const colors = ["navy", "grey", "camel", "white", "black"];
  const out: CandidateItem[] = [];
  for (const cat of cats) {
    for (let i = 0; i < 4; i++) {
      out.push({
        id: `${cat}-${i}`,
        category: cat,
        colors: [colors[i % colors.length]],
        formality: 3,
        seasons: [],
        material: null,
      });
    }
  }
  return out;
}

const args = {
  band: [1.5, 4.5] as [number, number],
  weather: { tempC: 15, rain: false },
  season: "Summer",
  excludeItemIds: [],
  maxAccessories: 1,
};

/** Exactly what app/generate/actions.ts does, minus the AI call. */
function shortlist() {
  const combos = buildCandidates(closet(), args);
  const ranked = rankTopN(combos, { aesthetic: [], band: args.band, lean: [] }, combos.length);
  return diversify(ranked, 20).map((t) => t.items.map((i) => i.id).join("+"));
}

describe("regenerate determinism probe", () => {
  it("produces an identical shortlist on two consecutive runs", () => {
    const a = shortlist();
    const b = shortlist();
    console.log("shortlist size:", a.length);
    console.log("first 5 of run A:", a.slice(0, 5));
    console.log("first 5 of run B:", b.slice(0, 5));
    console.log("identical:", JSON.stringify(a) === JSON.stringify(b));
    expect(b).toEqual(a);
  });

  it("shows what the model actually chooses between (top 3 of the shortlist)", () => {
    const s = shortlist();
    console.log("top 3 candidates the re-ranker sees:", s.slice(0, 3));
    expect(s.length).toBeGreaterThan(0);
  });
});

