import { buildCandidates, missingCategory, eligibleByCategory, type CandidateItem } from "@/lib/generator/candidates";
import { rankTopN } from "@/lib/generator/rank";
import { diversify } from "@/lib/generator/diversity";
import { currentSeason } from "@/lib/generator/season";

/** The real local closet, dumped from postgres 2026-07-28. */
const RAW = `89c5b72c|Bottoms|black|3|Autumn,Winter,Spring,Summer|Viscose
24cefffe|Bottoms|cream,white|3|Spring,Summer,Autumn,Winter|cotton
ba79e8dd|Bottoms|charcoal,black|3|Summer,Spring,Autumn|Lyocell
091a700e|Bottoms|black|3|Spring,Summer|Wool
51eebea9|Bottoms|cream|3|Spring,Summer,Autumn,Winter|cotton
c7002898|Bottoms|cream,beige|3|Spring,Summer,Autumn|Lyocell
acfbd844|Outerwear|black|3|Spring,Autumn|Polyester, Viscose
d61886c0|Shoes|cream,beige|3|Spring,Summer,Autumn,Winter|leather
3f9cc66e|Shoes|white,cream|3|Spring,Summer,Autumn,Winter|leather
2c66be67|Shoes|white,light blue|2|Spring,Summer,Autumn,Winter|leather
7a38d3db|Tops|white|3|Spring,Summer,Autumn,Winter|cotton
ffd96d06|Tops|light blue,white|3|Spring,Summer,Autumn,Winter|cotton
c776d37e|Tops|cream,beige|3|Spring,Summer,Autumn,Winter|Cotton knit
be0d9b74|Tops|black|2|Spring,Summer|Viscose
c23a46f9|Tops|white|4|Spring,Summer,Autumn,Winter|cotton
b805e5a8|Tops|white|3|Spring,Summer|Linen
bd4b63ea|Tops|white|3|Spring,Summer|Linen
7081d273|Tops|brown|3|Spring,Autumn,Winter|Cotton
9e2ba900|Tops|cream,ivory|3|Spring,Summer,Autumn,Winter|knit
16b55f79|Tops|black,gold|3|Autumn,Winter|Cotton
6a1fb679|Tops|navy|3|Spring,Autumn,Winter,Summer|Cotton`;

const items: CandidateItem[] = RAW.split("\n").map((l) => {
  const [id, category, colors, formality, seasons, material] = l.split("|");
  return { id, category, colors: colors.split(","), formality: Number(formality), seasons: seasons.split(","), material };
});

const OCCASIONS: [string, [number, number]][] = [
  ["Everyday", [1.5, 3]], ["Work", [3, 4.5]], ["Weekend", [1.5, 3.5]], ["Evening", [3.5, 5]],
];
const SEASONS: [string, number][] = [
  ["Spring", 14], ["Summer", 24], ["Autumn", 12], ["Winter", 3],
];

/** The exact production pipeline from app/generate/actions.ts, minus the AI call. */
function pipeline(band: [number, number], season: string, tempC: number, recentlyShown: string[] = []) {
  const args = { band, weather: { tempC, rain: false }, season, excludeItemIds: [], maxAccessories: 1 };
  const combos = buildCandidates(items, args);
  if (!combos.length) return { combos: 0, shortlist: [] as ReturnType<typeof diversify> };
  const ranked = rankTopN(combos, { aesthetic: [], band, lean: [], recentlyShown, season }, combos.length);
  return { combos: combos.length, shortlist: diversify(ranked, 20) };
}

describe("PR #14 + #15 + #16 composed, on the real closet", () => {
  it("no occasion x season combination is ever a dead end", () => {
    const dead: string[] = [];
    for (const [occ, band] of OCCASIONS) {
      for (const [season, tempC] of SEASONS) {
        const { combos } = pipeline(band, season, tempC);
        if (combos === 0) dead.push(`${occ}/${season}`);
      }
    }
    console.log(`dead ends: ${dead.length ? dead.join(", ") : "NONE"}`);
    expect(dead).toEqual([]);
  });

  it("the re-ranker always gets a full shortlist (PR #14 tiering survives)", () => {
    const sizes: string[] = [];
    for (const [occ, band] of OCCASIONS) {
      for (const [season, tempC] of SEASONS) {
        const { combos, shortlist } = pipeline(band, season, tempC);
        sizes.push(`${occ}/${season}=${shortlist.length}`);
        expect(shortlist.length).toBe(Math.min(20, combos));
      }
    }
    console.log(sizes.join("  "));
  });

  it("the day's top 3 never share a top or a bottom (PR #14 diversity survives)", () => {
    for (const [occ, band] of OCCASIONS) {
      for (const [season, tempC] of SEASONS) {
        const top3 = pipeline(band, season, tempC).shortlist.slice(0, 3);
        const tops = top3.map((c) => c.items.find((i) => i.category === "Tops")!.id);
        const bots = top3.map((c) => c.items.find((i) => i.category === "Bottoms")!.id);
        expect(new Set(tops).size, `${occ}/${season} tops`).toBe(3);
        expect(new Set(bots).size, `${occ}/${season} bottoms`).toBe(3);
      }
    }
  });

  it("regenerate changes the top 3 in every season (PR #15 survives seasons)", () => {
    const report: string[] = [];
    for (const [occ, band] of OCCASIONS) {
      for (const [season, tempC] of SEASONS) {
        const first = pipeline(band, season, tempC).shortlist.slice(0, 3);
        const shown = Array.from(new Set(first.flatMap((c) => c.items.map((i) => i.id))));
        const second = pipeline(band, season, tempC, shown).shortlist.slice(0, 3);
        const firstKey = first.map((c) => c.items.map((i) => i.id).sort().join("+")).sort().join("|");
        const secondKey = second.map((c) => c.items.map((i) => i.id).sort().join("+")).sort().join("|");
        const changed = firstKey !== secondKey;
        report.push(`${occ}/${season}=${changed ? "differs" : "SAME"}`);
        expect(changed, `${occ}/${season} regenerate produced an identical set`).toBe(true);
      }
    }
    console.log(report.join("  "));
  });

  it("in-season pieces lead the shortlist (PR #16 ordering reaches the model)", () => {
    // Winter: the two winter-only tops must appear ahead of the summer-only ones.
    const { shortlist } = pipeline([1.5, 3.5], "Winter", 3);
    const firstTops = shortlist.slice(0, 5).map((c) => c.items.find((i) => i.category === "Tops")!.id);
    const summerOnly = ["be0d9b74", "b805e5a8", "bd4b63ea"]; // tagged Spring,Summer only
    const leadHasSummerOnly = firstTops.filter((t) => summerOnly.includes(t)).length;
    console.log(`winter lead tops: ${firstTops.join(",")}  (summer-only in lead: ${leadHasSummerOnly})`);
    expect(leadHasSummerOnly).toBe(0);
  });

  it("real heat drops nothing from this closet — it has no insulation", () => {
    const hot = eligibleByCategory(items, {
      band: [1.5, 3.5], weather: { tempC: 32, rain: false }, season: "Summer", excludeItemIds: [], maxAccessories: 1,
    });
    // The wool trousers must SURVIVE — fibre alone never decides.
    expect(hot.Bottoms.map((i) => i.id)).toContain("091a700e");
    console.log(`at 32C -> tops ${hot.Tops.length}, bottoms ${hot.Bottoms.length}, shoes ${hot.Shoes.length}; wool trouser kept: ${hot.Bottoms.some(i => i.id === "091a700e")}`);
  });

  it("rain never empties a slot, even though 3 of 3 shoes could be excluded", () => {
    const wet = { band: [1.5, 3.5] as [number, number], weather: { tempC: 14, rain: true }, season: "Autumn", excludeItemIds: [], maxAccessories: 1 };
    expect(missingCategory(items, wet)).toBeNull();
    expect(buildCandidates(items, wet).length).toBeGreaterThan(0);
  });

  it("today's real season resolves correctly", () => {
    console.log(`currentSeason(now) = ${currentSeason(new Date("2026-07-28T12:00:00Z"))}`);
    expect(currentSeason(new Date("2026-07-28T12:00:00Z"))).toBe("Summer");
  });
});

